export function theLeaderParams(r){
 const t={...DEFAULTS,...r.talents.bb},sk=k=>r.skills.find(s=>s.prefabKey===k);
 const anim=k=>({duration:CLOCK.durations[k],release:CLOCK.events[k][0]});
 const chain=(k,clipKey,maxTargets)=>({key:sk(k).bbStr.enemy_key,cooldown:sk(k).cooldown,initial:sk(k).initCooldown,maxTargets,anim:anim(clipKey)});
 const sacrifice=(k,clipKey)=>({key:sk(k).bbStr.enemy_key,cooldown:sk(k).cooldown,initial:sk(k).initCooldown,max:sk(k).bb.max_target,
  scale:sk(k).bb.scale,duration:sk(k).bb.duration,anim:anim(clipKey)});
 return {
  shotSpeed:10,chain:{radius:sk("Chain_1").bb.range_radius,speed:10},sacrifice:{speed:3},
  arson:anim("Skill_b_3"),rebirth:t["Reborn.duration"],rebornHp:1,invincible:t["Reborn.invincible"],
  form1:{attackAnim:{dur:CLOCK.durations.Attack_a,hit:CLOCK.events.Attack_a[0]},rangedTargets:1,melee:{scale:1,followUps:[]},
   chain:chain("Chain_1","Skill_a_1",1),sacrifice:sacrifice("Sacrifice_1","Skill_a_2")},
  form2:{attackAnim:{dur:CLOCK.durations.Attack_b,hit:CLOCK.events.Attack_b[0]},rangedTargets:2,atk:t["AtkUp.atk"],
   melee:{scale:t["Combat_scale.atk_scale"],followUps:[CLOCK.events.Combat_b[1]-CLOCK.events.Combat_b[0]]},
   chain:chain("Chain_2","Skill_b_1",2),sacrifice:sacrifice("Sacrifice_2","Skill_b_2")},
 };
}
